// sort.ts
export function sort(arr: number[]): number[] {
    const len = arr.length;
    let swapped;

    do {
        swapped = false;
        for (let i = 0; i < len - 1; i++) {
            if (arr[i] > arr[i + 1]) {
                [arr[i], arr[i + 1]] = [arr[i + 1], arr[i]];
                swapped = true;
            }
        }
        len--; // Reduce the length for the next iteration
    } while (swapped);

    return arr;
}
```

